contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We test that SetLogFile can only succeed before Initialized(); once Initialized() has been called,
    // subsequent SetLogFile must revert. To observe behavior without relying on internal flags,
    // we call SetLogFile once, then call Initialized(), then attempt SetLogFile again and record whether it reverted.
    function run(address log1, address log2) public payable {
        // No precondition on inputs; operate only through c's public API.

        // First attempt to set the log file: capture whether it reverts.
        bool firstReverted;
        c.SetLogFile(log1); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            firstReverted = true;
        } else {
            firstReverted = false;
        }

        // Call Initialized() to flip the initialized flag (may revert if reentrancy or other issues, but it's public nonReentrant_)
        bool initReverted;
        c.Initialized(); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            initReverted = true;
        } else {
            initReverted = false;
        }

        // Second attempt to set the log file after calling Initialized(): should revert whenever Initialized() succeeded.
        bool secondReverted;
        c.SetLogFile(log2); bool __rev2 = __ESBMC_reverted(); if (__rev2) {
            secondReverted = true;
        } else {
            secondReverted = false;
        }

        // General property:
        // If the call to Initialized() succeeded (did not revert), then the second SetLogFile must revert.
        // We don't assert anything about the first SetLogFile (it may or may not revert depending on prior state),
        // but once Initialized() succeeded it must prevent SetLogFile from succeeding.
        assert(!(initReverted == false && secondReverted == false));
    }

    receive() external payable {}
}

